  function searchCities(query, limit) {
    limit = limit || 15;
    var q = String(query || '').trim().toLowerCase();
    if (!q) return [];
    var starts = [];
    var contains = [];
    for (var i = 0; i < RU_CITIES.length; i++) {
      var name = RU_CITIES[i][0];
      var lat = RU_CITIES[i][1];
      var lon = RU_CITIES[i][2];
      var lower = name.toLowerCase();
      if (lower.indexOf(q) === 0) {
        starts.push({ name: name, lat: lat, lon: lon });
      } else if (lower.indexOf(q) !== -1) {
        contains.push({ name: name, lat: lat, lon: lon });
      }
    }
    return starts.concat(contains).slice(0, limit);
  }

  window.MMSearchCities = searchCities;
